(() => {
  'use strict';
  // Each idea supplies a distinct scene; the copyable prompt adds its complete
  // art direction, crop instructions and the visitor's current site palette.
  const categories = [
    { id: 'people', name: 'People & workshops', style: 'Create an editorial documentary photograph of fictional adults in contemporary New Zealand. Use natural expressions, believable anatomy, ordinary well-made clothing, tactile everyday surroundings and available light. The atmosphere is warm, capable and unforced. Keep faces and hands anatomically convincing; avoid corporate stock-photo staging.', ideas: [
      ['The listening circle', 'In-house workshops hero', '16:9', 'A workshop that feels like a real conversation.', 'A small group of six adults of varied ages sit in a loose semicircle in a bright, modest Christchurch meeting room. One person speaks while the others listen with relaxed attention. A facilitator sits at the same level. Show coffee cups, unbranded notebooks and a window opening onto soft garden greenery. Frame the group on the right, with a calm plaster wall on the left for a website headline.'],
      ['A shared next step', 'Team workshop feature', '4:3', 'The useful moment when a team finds a way forward.', 'Photograph four colleagues leaning over a table, jointly arranging blank coloured cards into a simple path. Focus on the interaction between hands and faces, with one person gently indicating the next card. The room has timber furniture and broad overcast window light. Use a three-quarter overhead angle so the activity reads clearly without inventing legible writing. Make the collaboration feel thoughtful rather than celebratory.'],
      ['One good question', 'Individual coaching section', '4:5', 'A quiet conversation with room to think.', 'Show two fictional adults sitting in comfortable chairs at a slight angle to each other in a simple light-filled coaching space. The listener holds an unbranded closed notebook; the other person is mid-thought, looking toward the window. Include an ordinary side table and a glass of water. Frame at eye level with breathing space around both people. Capture trust through posture and attention, with no exaggerated emotion.'],
      ['Before everyone arrives', 'Workshop introduction', '16:9', 'An inviting room, prepared with care.', 'Show a facilitator in their forties making the final small adjustments to a community workshop room before participants arrive. Six chairs form an open circle, blank notebooks are placed on a side table, and morning light falls across the floor. Photograph from the doorway, placing the facilitator in the far right third. Let the empty space feel welcoming and ready, not lonely or grand.'],
      ['A different perspective', 'Support professionals training', '4:3', 'Two practitioners compare ideas during a learning break.', 'Capture two fictional support professionals talking beside an open window during a workshop break. One holds a plain ceramic mug while the other gestures softly with an open hand. Through the window, show a believable suburban New Zealand garden. Their expressions are interested and reflective. Use a medium close composition, soft side light and a shallow but credible depth of field.'],
      ['The small breakthrough', 'Workshop benefits card', '1:1', 'Recognition, without the staged celebration.', 'Photograph a participant at a workshop having a quiet moment of recognition: a slight smile, a relaxed brow, a pen paused above a notebook with blank pages. Two other participants remain softly visible in the background, engaged in their own work. Use a close crop with the face slightly off centre. The feeling is useful understanding and renewed agency, expressed subtly.'],
      ['Learning outside', 'Workshops lifestyle image', '16:9', 'A change of setting makes room for fresh thinking.', 'Show five adults taking a short reflective walk together through an ordinary New Zealand park after a workshop session. Space them naturally in pairs and one individual, with varied walking speeds and relaxed conversation. Use an accessible gravel path, established trees and early afternoon light. Photograph at walking height from a respectful distance, leaving sky and foliage open on the upper left.'],
      ['Making space for everyone', 'Team connection section', '4:3', 'Participation that feels comfortable and natural.', 'Photograph a contemporary workshop table where an adult wheelchair user, two seated colleagues and a standing facilitator are comfortably involved in the same small-group exercise. The table height and circulation space should be physically plausible. Show blank cards, pencils and simple mugs. Focus on an ordinary shared moment of concentration, using the same visual attention for every person.'],
      ['A conversation in pairs', 'Training format card', '3:2', 'A small, practical exercise in listening.', 'Show a workshop room with three pairs of adults having quiet conversations. The foreground pair is in focus, sitting at a slight angle, one person listening while the other speaks. The other pairs are visible but softly blurred. Use simple furniture, daylight and a neutral wall; there is no presenter at a podium. The image should communicate participation and practical learning rather than a lecture.'],
      ['Leaving with something useful', 'Workshop closing section', '16:9', 'A gentle sense of momentum after a good session.', 'Capture the end of a small workshop: three people gathering plain notebooks and jackets while still talking, a facilitator near the doorway, afternoon light reaching across a timber floor. One participant pauses with a thoughtful smile rather than posing at the camera. Keep the setting modest and recognisably lived in. Compose movement toward the right, with quiet negative space on the left.']
    ]},
    { id: 'everyday', name: 'Everyday resilience', style: 'Create a grounded editorial lifestyle photograph featuring fictional people and ordinary contemporary New Zealand settings. Show resilience as a small repeatable practice, with emotional nuance rather than a dramatic transformation. Use natural light, realistic proportions, subtle texture and a quiet observational camera.', ideas: [
      ['The first five minutes', 'Individual coaching hero', '16:9', 'A small pause before a busy day.', 'An adult sits at a kitchen table early in the morning, both hands around a warm mug, looking out at a small garden. A closed laptop and a plain notebook are nearby, but the moment is unhurried. Morning window light touches one side of the face. Position the person on the right and leave the softly lit wall and table on the left open for copy.'],
      ['A walk around the block', 'Everyday practice card', '4:5', 'An ordinary reset between responsibilities.', 'Photograph an adult taking a short walk along a quiet Christchurch suburban footpath. Their phone is tucked away, shoulders are relaxed, and they notice the trees overhead. Include modest houses, a low garden fence and late afternoon shadows. Use an environmental portrait with plenty of room around the person, who is looking away from the camera. The scene should feel achievable on a normal workday.'],
      ['One page, one next step', 'Resources introduction', '4:3', 'Make the next action feel manageable.', 'Show an adult seated beside a window with a single blank sheet of paper, a pencil and a cup of tea. Their hand rests lightly on the page as if beginning to think. Keep the face partly outside the crop and make the objects feel naturally used. Photograph from a gentle side angle, with soft linen texture and a clear central focal point.'],
      ['A familiar hand', 'Connection and support card', '1:1', 'Support expressed through a small human gesture.', 'Create an intimate but respectful photograph of two adult friends at a kitchen table, one placing a reassuring hand beside the other person’s hand, leaving a natural small gap. Include the edge of two cups and a folded tea towel. Show only forearms and a partial profile; the gesture is companionable, not medical or dramatic. Use warm overcast daylight and realistic skin texture.'],
      ['The quiet seat', 'Reflective quotation background', '16:9', 'A person taking time without needing to perform.', 'Photograph a fictional adult sitting alone on a simple park bench facing a broad, calm open space. Their posture is comfortably upright, neither triumphant nor defeated. Place the person in the far right third and let soft grass, sky and distant trees occupy the rest. Use early evening light and a low-contrast atmosphere suited to a thoughtful website section.'],
      ['After the school run', 'Real-life resilience story', '4:3', 'A believable moment inside a full day.', 'Show an adult pausing beside a bicycle outside an ordinary New Zealand home after a busy morning. A helmet hangs from the handlebars, a plain tote bag rests in the basket, and the person looks toward a small patch of sun on the garden. The scene feels practical and lived in, with no visible addresses or logos. Use a candid medium-wide composition.'],
      ['Making room on the desk', 'Workplace wellbeing card', '1:1', 'A little order can create space to focus.', 'Capture someone clearing a small area on a real desk: moving a closed notebook aside, straightening a cup and leaving a clean blank sheet in the centre. Keep a few ordinary objects at the edges so the scene feels human rather than perfectly styled. Show hands only, from above at a slight diagonal, using gentle daylight and tactile paper surfaces.'],
      ['A reliable check-in', 'Community connection section', '3:2', 'Two friends keeping in touch, naturally.', 'Photograph two fictional adults of different generations sitting on the low edge of a garden wall, having a relaxed conversation. One has a reusable cup and the other a small bag of groceries. Use a familiar New Zealand residential setting, casual contemporary clothes and a gentle late-afternoon breeze. Capture connection through their body angles and attentive expressions, with no posing at the camera.'],
      ['A different way home', 'Change and flexibility story', '16:9', 'A small detour reveals a new possibility.', 'Show an adult choosing a riverside walking path instead of the busier street visible softly behind them. Photograph from a slight distance with the person small within the scene, moving toward open light. Include an ordinary pedestrian bridge and textured riverbank planting. Keep the path accessible and the mood curious, avoiding a dramatic adventure aesthetic.'],
      ['An evening reset', 'Closing CTA image', '4:3', 'The day can end with a little more space.', 'Create a quiet domestic photograph of a person opening a window at dusk while a plain notebook rests closed on a small table. A soft breeze moves an unpatterned curtain, with a blue-grey garden beyond. Show the person from behind, naturally and without theatrical gestures. Let the room remain warm and believable, with gentle contrast between indoor and outdoor light.']
    ]},
    { id: 'landscapes', name: 'New Zealand landscapes', style: 'Create a fine-art editorial landscape photograph in New Zealand, with geographically plausible landforms and vegetation. Use natural atmospheric depth, restrained colour grading and visible texture. The image should feel specific, calm and lived in, without travel-advertisement saturation or a fantasy landscape.', ideas: [
      ['A braided way forward', 'Homepage hero', '21:9', 'Many channels, one continuing journey.', 'An elevated view of a Canterbury braided river shows pale shingle islands and several blue-grey channels converging gently toward the distance. Soft cloud shadows move across the riverbed, with foothills faint on the horizon. Keep the river’s strongest diagonals in the right two-thirds, leaving a quiet pale gravel area at left for headline text. Use subdued early morning light and accurate physical scale.'],
      ['The headland after rain', 'About page header', '16:9', 'Light returning to a familiar coastline.', 'Photograph a green Banks Peninsula headland after a passing rain shower. The coastline curves inward around a sheltered bay; wet grass catches a narrow opening of sunlight, while clouds remain soft and layered. Use a viewpoint from a public walking track, with no buildings dominating the scene. The mood is grounded optimism, and the sea should look real rather than luminous.'],
      ['A place to catch your breath', 'Individual coaching hero', '16:9', 'Open space, soft light and no urgency.', 'Show an empty sandy beach on the New Zealand east coast at low tide, with a thin band of water reflecting clouded sky. A small line of dune grass sits on the right foreground, and low hills fade into the distance. Use generous open sky and an uncluttered horizon. Frame without people, boats or dramatic sunbursts, letting the ordinary scale feel restorative.'],
      ['The path through the trees', 'Resilience process section', '4:5', 'The next part of the path is enough.', 'Photograph a gently winding walking track through a temperate New Zealand beech forest. Sunlight reaches a small bend just ahead, but the entire route is not visible. Include leaf litter, slender trunks and a believable understory. Keep the path broad and calm rather than precarious. Compose vertically, with a clear route from the lower foreground toward the centre.'],
      ['Still water, moving sky', 'Testimonial backdrop', '16:9', 'A quiet surface with life beyond it.', 'A small South Island lake reflects a changing overcast sky, with distant low hills and a strip of reeds along one shore. Avoid iconic postcard framing. Use a close-to-water viewpoint and a slightly imperfect reflection disturbed by a breeze. Leave the centre-left water visually quiet for a quote, keeping brighter detail on the far right.'],
      ['Above the weather', 'Leadership training header', '21:9', 'Perspective without the summit cliché.', 'Photograph a rolling New Zealand hill landscape from a moderate ridge, with a low ribbon of mist sitting in the valley below. The foreground is textured tussock, not a climber or a flag. The distant light opens gradually rather than bursting through clouds. Use soft dawn colour and a horizontal composition where layered slopes create calm depth.'],
      ['The estuary at low tide', 'Resources page header', '16:9', 'Patterns that reveal themselves when things slow down.', 'Create an aerial photograph of a New Zealand estuary at low tide, where shallow channels curve through pale sand and muted saltmarsh. The channels create an organic branching composition that remains geologically believable. No human figure is needed. Place the densest detail toward the bottom right, leaving a spacious upper-left area with soft tonal variation.'],
      ['A clearing, not an ending', 'Closing CTA background', '16:9', 'An opening that invites a next step.', 'Photograph a small grassy clearing at the edge of a New Zealand forest, seen from within the shade. A soft opening of daylight falls across the grass, and the distant view remains modest rather than epic. Include believable tree species and irregular natural edges. Keep the clearing on the right with quiet darker foliage at left, suitable for light-coloured website copy.'],
      ['Weather passing through', 'Change and resilience feature', '3:2', 'A landscape can hold more than one kind of weather.', 'Show a broad rural New Zealand valley with sunshine on the near fields and a passing rain shower far in the distance. The dividing line between light and cloud should feel gradual and physically plausible. Include simple fence lines and distant shelterbelts for scale, without readable signage. Capture the scene from ordinary ground level, quietly observing change.'],
      ['A river beside the city', 'Contact page image', '4:3', 'Grounding close to everyday life in Christchurch.', 'Photograph a peaceful stretch of the Avon River in Christchurch with overhanging deciduous trees, an ordinary footpath and a simple pedestrian bridge in the distance. Keep buildings understated and avoid landmark spectacle. A light breeze gives the water small ripples. Compose with a clear foreground bank and gentle mid-morning light, making the scene feel accessible and familiar.']
    ]},
    { id: 'maps', name: 'New Zealand reimagined', style: 'Create an original conceptual image built around a geographically recognisable map silhouette of New Zealand. Preserve the North Island, South Island, Stewart Island and the spaces between them, using an accurate coastline reference if available. Keep the land shapes proportionally believable. Present the map as a material or spatial idea, with no labels or text.', ideas: [
      ['An island of small possibilities', 'Homepage hero artwork', '16:9', 'A New Zealand map made of tiny open doors.', 'Build a freestanding New Zealand silhouette from many miniature plain door frames, arranged close together at varied heights on an ivory studio surface. Most doors are slightly open, with soft warm light passing through. The overall coastline remains recognisable from a high three-quarter angle. Keep the map on the right, leaving the left half open. Use clean contemporary model-making and subtle real shadows.'],
      ['A landscape in folded paper', 'About page hero artwork', '16:9', 'The country as a delicate, dimensional paper landscape.', 'Construct the New Zealand land shapes from softly folded heavyweight paper, with low geometric ridges suggesting the main mountain spine. Use five harmonious paper colours for land, shadow and small inland details. Float the shapes just above a matte surface to create fine contact shadows. View from almost directly above, placing the full map in the right two-thirds with all islands visible.'],
      ['Held together by light', 'Connection section artwork', '4:3', 'Small points of light create a shared shape.', 'Form a New Zealand silhouette from hundreds of tiny softly illuminated glass beads resting on a dark matte surface. Beads cluster densely enough to preserve the coastline, with a few fine luminous links suggesting connection between nearby points. Avoid a digital network dashboard appearance. Photograph the physical installation from above, with restrained glow and beautiful small reflections.'],
      ['The living contour', 'Programme model introduction', '4:5', 'A map carved into gentle layers of terrain.', 'Create a topographic New Zealand relief sculpted from pale stone, with shallow contour terraces and softly rounded edges. Place it vertically in the composition on a warm neutral background. Use side lighting to reveal the layers, without placing labels, roads or markers. The relief should feel tactile and contemporary, like a carefully made architectural model.'],
      ['A collection of steady stones', 'Resilience values artwork', '1:1', 'Different pieces forming one recognisable place.', 'Arrange smooth naturally varied river stones to create an accurate New Zealand silhouette on a pale sandy surface. Choose complementary muted colours and varied sizes, keeping the coastline readable through careful placement. Use overhead photography with gentle morning side light. The stones rest normally on the surface, with no balancing towers or gravity-defying arrangement.'],
      ['An opening in the clouds', 'Wide page header', '21:9', 'A familiar shape revealed by a pause in the weather.', 'Create a conceptual aerial image of a soft cloud field with a clear opening shaped precisely like New Zealand. Through the opening, reveal calm deep blue water rather than land. Keep the edges atmospheric while the three principal island shapes remain identifiable. Place the map-shaped openings toward the right half; leave smooth cloud mass on the left for a headline. Use plausible sunlight and restrained contrast.'],
      ['Threads of connection', 'Support professionals section', '4:3', 'A map built from many individual threads.', 'Lay plain fine cotton threads in loosely parallel curves that collectively create the shape of New Zealand on an untextured neutral board. Some threads run continuously through each island and others meet softly at points, suggesting connection without a rigid network diagram. Keep the artwork minimal and contemporary, with no decorative motifs. Use a near-overhead camera and gentle shadows that make every strand tangible.'],
      ['A glass country', 'Modern hero illustration', '16:9', 'Translucent colour gives the land a new dimension.', 'Create a single sculptural New Zealand map cut from thick translucent cast glass, including separate correctly positioned main islands. The glass has softly rounded coastline edges and a restrained internal colour gradient. Place the sculpture flat on a matte surface and light it from a low side angle so subtle coloured caustics spill to the right. The physical object occupies the right half of the frame.'],
      ['Room to grow', 'Growth and possibility section', '4:5', 'An island silhouette formed by a miniature garden.', 'Build a small New Zealand-shaped garden on a clean studio plinth, using short meadow grasses, tiny ordinary white flowers and patches of visible dark soil. Keep vegetation low enough that the coastline remains clear. Photograph at a high three-quarter angle with soft daylight. The miniature landscape should feel biologically plausible and carefully tended, with no buildings or signs.'],
      ['A coastline drawn by water', 'Background or section divider', '21:9', 'The shape of New Zealand in a single gentle ripple.', 'Create a top-down conceptual photograph of still shallow water where a low transparent mould creates New Zealand-shaped ripples. The principal land outlines are defined by a few fine wave rings, including the gaps between islands. Use warm pale sand beneath the water, subtle blue reflections and sunlight from one side. Keep the map in the right two-thirds with quiet water surrounding it.']
    ]},
    { id: 'metaphors', name: 'Visual metaphors', style: 'Create a sophisticated conceptual still-life image for a practical resilience website. Make the metaphor immediately legible through material, scale and composition, without words or explanatory labels. Use physically credible studio lighting, restrained surrealism, tactile surfaces and a calm contemporary editorial finish.', ideas: [
      ['The flexible line', 'Resilience model hero', '16:9', 'Strength that can adapt.', 'A long thin strip of brushed metal bends smoothly around a rounded stone and continues forward without breaking. Rest both objects on an ivory tabletop with a subtle horizon. The line should look springy rather than sharp, and the stone should feel ordinary and grounded. Place the objects on the right, with a soft shadow guiding the eye back into the composition.'],
      ['One small bridge', 'Next steps CTA', '4:3', 'A manageable connection across a small gap.', 'Two low blocks of textured clay sit a short distance apart, connected by a simple narrow wooden footbridge sized for a miniature landscape. The gap is modest and the bridge looks stable. Add no people, flags or ladders. Use a low three-quarter view, an uncluttered background and soft natural side light to make the idea of a practical next step clear.'],
      ['The knot loosens', 'Individual coaching feature', '1:1', 'A problem becoming easier to work with.', 'A plain thick cotton cord lies on a smooth surface, with a loose central knot gently opening into two clear lines. The knot must be physically possible and easy to read. Use an overhead camera, warm textured fibres and restrained shadows. Keep the composition spacious, with the cord entering from one side and continuing toward the other, suggesting progress rather than a finished solution.'],
      ['A place for the weight', 'Support and connection card', '4:5', 'Support can change how a burden feels.', 'A heavy smooth stone rests securely in a shallow cradle formed by three simple wooden supports. Show the supports sharing the load in a physically credible arrangement. Keep the design elegant and minimal, with no human figures. Use a close studio photograph with tactile stone grain, fine timber texture and a soft shadow below. The result should feel steady and reassuring.'],
      ['The next visible step', 'Coaching process section', '16:9', 'You do not need the whole route to begin.', 'Create three broad low steps cut into a matte sculptural landscape. The first two are clearly lit and the third fades softly into a gentle atmospheric haze. The steps are wide and accessible, not steep or threatening. Position the structure to the right of frame, leaving generous blank space at left. Use a quiet architectural photography style and a warm, believable light source.'],
      ['A little more room', 'Stress and perspective feature', '4:3', 'Space changes what becomes possible.', 'Photograph a cluster of plain coloured wooden blocks on a tabletop, with one block moved slightly aside to create an open passage of light through the centre. The blocks should remain grounded and practical, not a puzzle with an obvious winner. Show the small opening clearly from a low angle. Use soft studio light and fine surface texture.'],
      ['A steadying counterweight', 'Balance and wellbeing card', '1:1', 'Balance as an ongoing adjustment.', 'A simple sculptural mobile hangs from one fine cord, with three rounded forms of different sizes balanced at slightly different heights. Use a physically credible arrangement of rods and weights, and a pale seamless background. Capture a barely perceptible sense of movement through the differing angles. Avoid perfect symmetry; the balance should feel responsive and alive.'],
      ['The seed and the crack', 'Growth section image', '4:5', 'A small opening makes growth possible.', 'Create a macro photograph of a tiny green seedling emerging through a narrow gap between two smooth pieces of pale clay. The seedling has two believable young leaves, delicate stem texture and a trace of soil. The crack is a natural small opening, not destruction. Use low side light and very shallow depth of field, leaving the upper part of the frame quiet.'],
      ['The joined horizon', 'Teamwork hero artwork', '16:9', 'Different perspectives become a shared view.', 'Arrange five small rectangular mirrors on a plain surface at slightly different angles, each reflecting part of the same simple landscape of sky and low hills. Together their reflections suggest a continuous horizon, though their edges remain visible. Use a high-end editorial still-life style with subtle shadows and no camera reflection. Place the mirrors on the right to leave headline space at left.'],
      ['A change in direction', 'Adaptability section', '3:2', 'An obstacle can redirect movement.', 'A clear stream of water on a shallow matte tray flows around a single smooth pebble, forming two gentle paths that meet again beyond it. Use an overhead close-up where the movement is visible through soft ripples and reflected light. The water should behave realistically. Keep the pebble slightly right of centre and the surrounding composition simple and unhurried.']
    ]},
    { id: 'illustration', name: 'Editorial illustrations', style: 'Create an original contemporary editorial illustration with flat shapes, a few confident hand-drawn contours and light paper grain. Use thoughtful negative space, simple expressive forms and restrained mixed colours. Avoid clip-art, mascots, emoji styling, tiny decorative clutter and glossy 3D rendering. Any people are fictional and naturally proportioned.', ideas: [
      ['A conversation opens a window', 'Individual coaching hero', '16:9', 'Listening creates a fresh outlook.', 'Illustrate two adults seated at a small round table. Between them, an oversized open window reveals a simple horizon with low hills and a pale sun. The window is a visual metaphor, integrated lightly into the room rather than held by either person. Place the scene in the right half. Use simple relaxed body language and no speech bubbles or text.'],
      ['A toolkit for real life', 'Resources page hero', '4:3', 'A useful set of simple, adaptable tools.', 'Illustrate an open plain toolbox containing a small compass, a blank notebook, a smooth stone, a simple key and a sprouting plant. Each object is distinct and calmly arranged, suggesting reflection, direction, grounding and growth. The toolbox should feel contemporary and friendly, without literal labels. Use a three-quarter viewpoint and broad quiet shapes with soft hand-drawn edges.'],
      ['Many ways to take part', 'Workshops feature grid', '16:9', 'Everyone contributes in a different way.', 'Illustrate a group of six adults arranged around a loose circle, some seated on chairs, one using a wheelchair, and one standing beside a table. Each person contributes a simple coloured shape to the shared centre. Give everyone equal visual importance and natural body proportions. Keep the background largely empty and use subtle overlaps to create connection.'],
      ['A map of small choices', 'Resilience model explainer', '4:5', 'A journey made of approachable decisions.', 'Draw a gentle branching path through a minimal imagined landscape of rounded hills and simple trees. Three small human figures choose different routes, each leading toward a quiet open area. Avoid a maze, finish line, trophy or arrows with labels. Use an elevated diagram-like perspective, clear separation between paths and a calm sense of possibility rather than competition.'],
      ['The pause between waves', 'Reflective quote artwork', '16:9', 'Calm can exist inside movement.', 'Illustrate broad flowing ocean-like bands with a small still oval of pale space between them. A simple seated figure rests at the edge of this quiet space, looking outward. Keep the waves abstract and gentle rather than threatening. Use layered flat colour, lightly textured edges and a wide composition with plenty of open area for website copy.'],
      ['Different shapes, shared space', 'Team connection card', '1:1', 'Belonging without everyone becoming the same.', 'Create an arrangement of varied geometric forms sharing one large soft-edged container shape. The forms differ in size, colour and orientation, with small spaces between them so each remains distinct. Add two subtle hand-drawn lines suggesting conversation or movement. The image should feel like an editorial idea about teams, not a preschool shape puzzle.'],
      ['A thought with room around it', 'Wellbeing resource card', '4:3', 'Perspective can make a thought easier to hold.', 'Illustrate a small tangled line floating inside a large clear softly rounded frame. Outside the frame, place a simple chair, a plant and an open window as grounding everyday elements. Keep the tangle light and manageable, with space surrounding it. Use spare linework and a balanced off-centre composition, without heads, brains, speech bubbles or written labels.'],
      ['People who hold the space', 'Support professionals header', '16:9', 'Support work as a shared, capable practice.', 'Illustrate three adults gently holding the edges of a large translucent sheet that forms a soft sheltered space above an empty chair. Their posture is ordinary and grounded, and the sheet curves naturally between their hands. The metaphor should feel warm and practical, with no heroic poses. Keep the left third mostly clear and the scene on the right.'],
      ['Small habits, growing roots', 'Everyday practice section', '4:5', 'Repeated actions build something beneath the surface.', 'Show a simple cutaway illustration of a small plant above ground and a beautifully clear branching root system below. Beside the plant sit a cup, a closed notebook and a pair of walking shoes, all drawn with economical shapes. Connect the scene through composition rather than arrows. Keep the roots botanically plausible and the mood quiet and constructive.'],
      ['A shared horizon', 'Homepage closing section', '21:9', 'People moving toward possibility together.', 'Illustrate four small adults walking at different paces along a gently rising path toward a wide open horizon. Leave generous distance between the figures; some walk in conversation and one walks reflectively alone. Use simplified low hills, one tree and a soft sun partly outside the frame. Keep the path broad and the scene grounded, with no summit, race or finish line.']
    ]},
    { id: 'materials', name: 'Paper & clay worlds', style: 'Create a photograph of an original handcrafted miniature set made from paper, card, clay or wood as specified. Show convincing material grain, imperfect cut edges and soft real contact shadows. The scene is sophisticated and editorial, with careful studio lighting, simple forms and no toy-brand resemblance.', ideas: [
      ['The paper clearing', 'About header artwork', '16:9', 'An opening in a layered paper forest.', 'Construct a miniature forest from upright folded paper shapes, with a small clear path leading to a circular opening of warm light. Use no more than twelve trees and keep their forms simple, without intricate ornament. Photograph at miniature eye level so the layers create depth. Position the clearing on the right and leave softly blurred paper layers at left for copy.'],
      ['A landscape you can hold', 'Individual coaching card', '1:1', 'A small world with a manageable next step.', 'Create a palm-sized clay landscape resting on a plain plinth, featuring two low hills, a short path and a tiny open gate. No hand or person appears. Make the clay matte, slightly textured and softly imperfect. Photograph from a high three-quarter angle with a single broad light source. Keep the path and gate legible at a small website-card size.'],
      ['The fold that becomes a bridge', 'Change and learning feature', '4:3', 'A familiar material gains a new purpose.', 'Show a single sheet of heavyweight coloured paper folded into a simple low bridge over a narrow gap between two card platforms. The folds must be physically plausible and the sheet clearly continuous. Use a clean studio surface, crisp but gentle shadows and a three-quarter view. Avoid additional objects so the transformation is the entire idea.'],
      ['A place at the table', 'Workshops section image', '4:3', 'A welcoming miniature room for shared learning.', 'Build a carefully crafted miniature workshop room with six small plain clay chairs around an open centre, a low timber table and one broad paper window. There are no people, writing or screens. Use a warm overhead light and natural material texture. Photograph from above at a slight angle, letting the empty chairs communicate an invitation.'],
      ['The gentle staircase', 'Coaching process artwork', '4:5', 'Progress in small, comfortably sized steps.', 'Make a sculptural staircase from five rounded clay blocks, each rising only slightly above the last. A small paper door stands open at the top, leading into empty space rather than a room. Keep the proportions deliberately miniature but physically credible. Use soft side light, a matte background and a clear vertical composition.'],
      ['An island of calm', 'Quote or pause section', '16:9', 'A small still place within a flowing world.', 'Create a miniature rounded island of matte clay surrounded by layered curved strips of paper that suggest slow-moving water. On the island place one simple empty chair and a tiny paper tree. Keep the forms restrained and the scene open, avoiding cute character styling. Photograph from a three-quarter angle with enough space on the left for a quotation.'],
      ['The movable wall', 'Flexible thinking card', '1:1', 'An opening can be made.', 'Build three simple cardboard wall panels on a tabletop, with the middle panel gently pivoted open to reveal a patch of light behind. Show the cut edges and a plausible hinge detail. Use a low camera angle so the opening is clear and inviting. Keep the geometry quiet, the colours mixed but restrained, and the physical construction believable.'],
      ['The shared canopy', 'Team resilience image', '3:2', 'Support made from several small contributions.', 'Create a freestanding miniature canopy formed from five overlapping paper arches, each supported by its own pair of simple clay feet. The arches share a sheltered open space beneath them. Use a minimal studio set and gentle side light. Show the connections through overlap and shadow, keeping the structure plausible and visually calm.'],
      ['A pocket-sized perspective', 'Resources card', '4:5', 'A little distance reveals a bigger picture.', 'Photograph a tiny open cardboard viewing box that contains a layered paper landscape of hills and sky. The box sits on a clean table and is seen at an angle so its depth is obvious. A small circular aperture on one side suggests a change in viewpoint. No person, text or branding appears. Use a tactile editorial craft aesthetic.'],
      ['Colour finds a way through', 'Hopeful CTA artwork', '21:9', 'Light turns a narrow gap into a possibility.', 'Arrange tall pale paper panels with one narrow gap between them. A restrained coloured light passes through the gap and spreads into a soft fan on the floor. Keep the lighting physically credible and the material grain visible. Place the panels toward the right and leave the left half open, with the cast light gently linking both sides.']
    ]},
    { id: 'textures', name: 'Light & textures', style: 'Create a refined abstract photographic background intended to sit behind website text. Use real material texture, low visual noise, restrained contrast and an uncluttered focal hierarchy. Avoid logos, writing, objects with meaning, harsh hotspots and busy all-over detail. Preserve subtle tonal separation without banding.', ideas: [
      ['Light through linen', 'Hero or quotation background', '21:9', 'Soft movement and a generous quiet area.', 'Photograph sunlight filtering through a plain loosely woven linen curtain, creating broad overlapping folds and soft shadows. Keep the weave visible only near the right edge and let the left two-thirds resolve into a calm pale field. The folds should feel natural and unarranged. Use a close crop with no window frame or room visible, and gentle highlights that never clip to white.'],
      ['Water on warm stone', 'Section background', '16:9', 'A little reflected movement on a grounded surface.', 'Show faint water-caustic reflections moving across a matte limestone wall. The stone texture is fine and tactile; the reflected light is broad and subtle rather than a busy swimming-pool pattern. Concentrate the reflections in the lower right corner and leave the upper left quiet. Use a warm-neutral base with a cool reflected tint.'],
      ['A horizon in colour', 'Wide CTA background', '21:9', 'Two soft fields meeting without a hard line.', 'Create a photographic abstraction of sea and sky so softly focused that they become two quiet colour fields. Preserve a very subtle horizontal meeting point below the centre, with the upper field larger. Use restrained atmospheric colour, a little natural grain and no recognisable objects. The result should feel like an observed landscape rather than a synthetic gradient.'],
      ['The shadow of a leaf', 'Resource card background', '4:3', 'A simple natural rhythm.', 'Photograph the soft shadow of one ordinary broad leaf on a textured unpainted paper surface. The actual leaf remains outside the frame. Position the shadow along the right edge and let it fade gently toward the centre. Use indirect afternoon light, fine paper fibres and a quiet matte finish. Avoid multiple overlapping leaves or a decorative botanical pattern.'],
      ['Mist as a material', 'Page header background', '16:9', 'Depth without visual clutter.', 'Create a close, abstract landscape photograph of low mist moving between three softly layered hills. Reduce the hills to simple broad shapes while retaining realistic atmospheric depth. Keep the darkest layer at the bottom right and the upper left almost empty. Use gentle tonal differences with no dramatic beams of light or sharp mountain peaks.'],
      ['Folded light', 'Feature section background', '3:2', 'A warm architectural fold.', 'Photograph two broad sheets of matte paper standing at a shallow angle, with soft side light creating a single curved shadow between them. Crop so the sheets fill the frame and no studio equipment is visible. Use fine paper texture and one subtly contrasting colour on the receding plane. Keep most of the image quiet enough for small website text.'],
      ['A slower ripple', 'Testimonial background', '16:9', 'Gentle concentric movement, held at the edge.', 'Photograph a single small set of ripples on still shallow water from directly above. The ripple centre sits outside the bottom-right edge, so only a few broad curved lines enter the frame. Let the remaining water be calm with a restrained reflection of overcast sky. Avoid sparkling highlights and busy debris; the effect is soft and spacious.'],
      ['Soft mineral layers', 'Card or banner background', '4:3', 'Subtle strata with a tactile finish.', 'Create a macro photograph of a smooth cut stone surface with three broad gently curved mineral bands. The texture should be finely detailed but low contrast, with no glitter or glossy varnish. Arrange the bands diagonally near the right side and leave one large quiet area at left. Use soft diffuse light and a restrained mixed-hue palette.'],
      ['The space between curtains', 'Wide header image', '21:9', 'A small opening, a soft glow.', 'Photograph a narrow vertical opening between two plain curtains, seen very close so the folds become abstract planes. The opening sits in the far right third and releases a soft glow, while the left remains a calm softly shaded fabric field. Use natural linen texture and diffused daylight. Keep the image understated and free of visible interior objects.'],
      ['A quiet wash of pigment', 'Section divider artwork', '16:9', 'Colour with a human, imperfect edge.', 'Create a high-resolution scan-like image of two broad translucent pigment washes on textured off-white paper. One wash gently overlaps the other near the lower right, producing a third harmonious colour. Preserve subtle pooling at the edges and realistic paper fibres. Keep the left half mostly untouched and avoid splatters, calligraphy, repeated patterns or any recognisable symbol.']
    ]},
    { id: 'details', name: 'Objects & details', style: 'Create a contemporary editorial still-life photograph with natural material texture, restrained styling and believable everyday objects. Use soft daylight or one large studio light, subtle shadows and a clean visual hierarchy. All notebooks, cards, packaging and screens are blank or unbranded, with no readable text.', ideas: [
      ['The workshop table', 'Workshop details image', '4:3', 'Everything ready for a useful conversation.', 'Photograph a timber table prepared with six plain notebooks, sharpened pencils, simple ceramic cups and a small glass water jug. Arrange the objects naturally around the edges, leaving a shared open space in the centre. Use an overhead view with soft window light entering from one side. The setting feels thoughtful and modest, with no excessive props or luxury styling.'],
      ['A notebook and a little daylight', 'Resources feature card', '4:5', 'An invitation to begin reflecting.', 'An open blank notebook rests on a linen-covered desk beside a simple pencil. A rectangle of soft morning light crosses the lower half of the page, and a small smooth stone holds the upper corner. Photograph from a slight diagonal above, showing paper grain and the worn edge of the pencil. Leave the upper third visually uncluttered.'],
      ['Three cups, one conversation', 'Team connection card', '1:1', 'Human presence without showing faces.', 'Show three different plain ceramic mugs gathered around the corner of a small table, with one empty chair softly visible behind. One mug is half full, another has a little steam, and the third sits beside a closed notebook. The objects suggest an ongoing conversation, not an abandoned room. Use warm natural light and restrained variations in colour and shape.'],
      ['A compass, used simply', 'Direction and values section', '4:3', 'Direction as a practical aid.', 'Photograph a small plain compass beside a folded unmarked paper map on a lightly textured surface. The compass is a believable simple instrument without a prominent brand, and the map has only very faint abstract terrain lines with no writing. Use a close overhead composition, with the objects grouped at the lower right and generous open space above.'],
      ['Cards in a new arrangement', 'Learning process card', '1:1', 'Reframing an idea through a small change.', 'Arrange seven blank rectangular cards on a neutral tabletop, most overlapping in a loose group while one sits slightly apart at a fresh angle. Use three harmonious colours rather than a rainbow. The cards have real paper thickness, lightly softened corners and fine shadows. Photograph from directly above with a crisp but gentle editorial finish.'],
      ['The doorway before a session', 'Contact or enquiry section', '4:5', 'A place that feels comfortable to enter.', 'Photograph a partially open plain timber door leading into a bright, modest meeting room. Through the opening, show the edge of two comfortable chairs and a simple side table. No person, sign, logo or room number appears. Use eye-level framing, soft daylight and a welcoming amount of detail, keeping the space believable rather than like a luxury hotel.'],
      ['A small collection of anchors', 'Grounding resources card', '4:3', 'Ordinary objects that invite attention.', 'Create an overhead still life of a smooth stone, a plain ceramic cup, a short pencil, a small leaf and a folded square of linen. Each object has space around it and a distinct tactile quality. Arrange them in an informal balanced composition rather than a symbolic diagram. Use diffuse daylight and fine natural shadows on a matte surface.'],
      ['The chair beside the window', 'Individual coaching image', '4:5', 'Room for one person and their next thought.', 'Photograph one comfortable contemporary armchair angled beside a large window in a simple coaching room. A plain side table holds a glass of water and a closed notebook. The chair is empty, with a softly creased cushion that feels lived in. Use a calm eye-level view and natural light, avoiding a medical setting or opulent interior.'],
      ['A pencil in motion', 'Practice and progress card', '3:2', 'A first mark, with plenty of room left.', 'Show a close photograph of an adult hand lightly holding a pencil above a blank page, just after drawing one simple short curved line. Keep the line abstract rather than a letter or symbol. Focus on realistic fingers, paper texture and the pencil tip, with the rest softly out of focus. The image should communicate a tentative useful start.'],
      ['The open gate', 'Next step CTA image', '16:9', 'An ordinary invitation to move forward.', 'Photograph a simple unpainted garden gate standing slightly open onto an accessible gravel path and soft greenery. The gate is modest and practical, not ornate or symbolic. Frame it on the right, with an uncluttered sunlit wall on the left for a headline. Use mild morning light and natural weathered timber texture, with no person or readable sign.']
    ]},
    { id: 'possibilities', name: 'Unexpected possibilities', style: 'Create an original imaginative editorial image with one clear visual idea, restrained surrealism and a physically convincing photographic finish. Combine ordinary materials with an unexpected change in scale or context. Keep the mood thoughtful and quietly hopeful, avoiding fantasy spectacle, glowing brains, heroic poses and motivational-poster clichés.', ideas: [
      ['A horizon inside a cup', 'Homepage feature artwork', '4:3', 'A small pause holds a wider perspective.', 'A plain ceramic cup sits on a real kitchen table, but its surface contains a tiny calm horizon of sea and sky, as if looking into a miniature world. Keep the cup and table fully realistic, with the horizon confined naturally within the rim. Use soft morning light and subtle reflections. The surreal element should be discovered quietly rather than announced with dramatic effects.'],
      ['A room with a moving sky', 'About hero artwork', '16:9', 'A familiar room, a different kind of outlook.', 'Show a simple meeting room whose far wall is a broad open view of slow-moving clouds over low New Zealand hills. The floor and two ordinary chairs remain physically grounded, with daylight entering consistently from the opening. Place the room elements on the right and leave a quiet pale wall at left. Make the transformation elegant and spatially believable, with no floating furniture.'],
      ['A landscape in a drawer', 'Resources library image', '4:3', 'Something useful waiting to be opened.', 'Photograph a plain timber desk with one shallow drawer pulled open. Inside is a carefully crafted miniature landscape with a simple path, low hills and a tiny pool of water. The scene is built from real-looking materials and fits within the drawer’s depth. Use a high three-quarter camera angle and soft daylight. Keep the desk otherwise clear and unbranded.'],
      ['The pocket of daylight', 'Coaching feature artwork', '4:5', 'A little possibility carried into the day.', 'A plain cotton jacket hangs on the back of an ordinary chair. Its open pocket contains a soft patch of daylight and a tiny folded-paper horizon, visible just above the seam. The garment and room are realistically photographed, while the miniature scene is carefully crafted and modest. Use close framing and gentle shadows, without a magical glow spreading beyond the pocket.'],
      ['An umbrella full of sky', 'Support professionals artwork', '1:1', 'Support can make room for a different outlook.', 'An open plain umbrella rests upside down on a matte studio floor, and its inner canopy holds a subtle reflected blue sky with a few soft clouds. The fabric ribs, handle and contact shadows remain realistic. Use a restrained overhead three-quarter composition with generous space around the object. Avoid rain, storms or people; let the single unexpected reflection carry the idea.'],
      ['The bookmark becomes a path', 'Resources page hero', '16:9', 'Learning that continues beyond the page.', 'An open blank book lies on a table, and a simple fabric bookmark extends beyond its edge into a miniature gently winding path across the surface. The path leads to a small paper doorway in the right half of the frame. Keep the materials tactile and the scale transition gradual. Use soft side light and leave the upper-left page mostly clear.'],
      ['A window folded from paper', 'New perspective section', '4:3', 'A new view made from an ordinary starting point.', 'Show a single sheet of heavy paper folded into a freestanding window frame on a clean tabletop. Through its opening, a small real-looking New Zealand coastal horizon appears, while the surrounding tabletop remains in the studio. The frame should have believable folds and thickness. Keep the illusion restrained, with consistent light and no visible screen or photograph mounted behind it.'],
      ['The stone that holds a garden', 'Resilience model artwork', '4:5', 'Steadiness and growth in the same object.', 'Create a close photograph of a large smooth river stone with a shallow natural-looking hollow containing a tiny living garden of moss, grass and one small ordinary flower. The stone rests securely on a pale surface. Use macro-level texture and soft side light, with no levitation or impossible roots. The garden should feel delicate but viable at its miniature scale.'],
      ['The conversation as a landscape', 'Teamwork hero artwork', '16:9', 'Two viewpoints creating shared ground.', 'Place two plain chairs facing each other across a small distance in a minimal studio. Between them, the floor rises gently into a miniature landscape of low hills and a winding path connecting the chairs. Keep the chairs life-sized and the landscape subtle, with credible shadows and material texture. Use a calm architectural photograph style, with no people or speech bubbles.'],
      ['A door at the edge of a page', 'Final CTA image', '21:9', 'An ending that offers a beginning.', 'An oversized blank sheet of textured paper curves gently upward at its far right edge, where a small plain door is cut into the paper and stands slightly open. Soft daylight falls through onto the flat sheet. The left two-thirds remain an uninterrupted warm neutral surface for website text. Use a real handcrafted set aesthetic with fine paper fibres, accurate shadows and no writing.']
    ]}
  ];

  const items = categories.flatMap((category, categoryIndex) => category.ideas.map((idea, index) => ({ id: `IMG-${String(categoryIndex * 10 + index + 1).padStart(3, '0')}`, category, title: idea[0], use: idea[1], ratio: idea[2], description: idea[3], scene: idea[4] })));
  const grid = document.getElementById('prompt-grid');
  const search = document.getElementById('prompt-search');
  const filters = document.getElementById('prompt-categories');
  const count = document.getElementById('prompt-count');
  const more = document.getElementById('prompt-more');
  const notice = document.getElementById('prompt-notice');
  const fallback = document.getElementById('prompt-copy-dialog');
  const fallbackText = document.getElementById('prompt-copy-text');
  let category = 'all', limit = 12, noticeTimer;
  const palette = () => {
    const api = window.HoeaAppearance;
    return api?.palettes.find(p => p.id === api.getState().palette) || { name: 'Tidal Bloom', colours: ['#175d62', '#b65d3e', '#8b73b2', '#82b6a4', '#d9d4c8'] };
  };
  function fullPrompt(item) {
    const p = palette();
    const photo = ['people', 'everyday', 'landscapes', 'details'].includes(item.category.id);
    return `Generate FOUR separate images. Each image must contain a clean 2×2 grid of four distinct variations: 16 variations in total. Do not combine the four output images into one larger grid.\n\nVariation plan (top-left, top-right, bottom-left, bottom-right in each image):\nImage 1 — photographic interpretations: candid documentary photography; cinematic environmental photography; tactile analogue-film photography; minimal fine-art studio photography.\nImage 2 — illustrated interpretations: textured editorial gouache; fluid watercolour and pencil; bold flat vector illustration; expressive ink and pastel.\nImage 3 — dimensional interpretations: layered cut-paper collage; handmade clay miniature; sculptural translucent glass; soft textile and felt assemblage.\nImage 4 — experimental interpretations: risograph print; restrained surreal photographic collage; geometric modernist poster artwork without lettering; atmospheric abstract painting that still makes the central idea recognisable.\n\nEach panel must be a fresh interpretation, not a duplicate, recolour, filter or minor edit of another panel. Vary composition, viewpoint, lighting, arrangement and visual storytelling as well as medium. Keep the core subject and purpose recognisable in all 16 panels. The scene brief below is the conceptual starting point; reinterpret its photography, material, lighting and camera instructions to suit each assigned style. Preserve meaningful details and any requested negative space within each panel.\n\nScene brief and original inspiration: ${item.category.style}\n\n${item.scene}\n\nArt direction: this image is for Hoea tō Waka, a New Zealand resilience training and coaching website. Communicate practical hope, warmth, human connection and space to think. Coordinate with the ${p.name} website palette: ${p.colours.join(', ')}. ${photo ? 'Use these colours subtly in clothing, props, light and surroundings; preserve believable skin, vegetation, water and sky colours. Do not apply a heavy overall colour filter.' : 'Use these colours as a considered mixed palette, balancing the deeper anchor with its contrasting accents and generous quiet neutrals rather than using every colour equally.'}\n\nOutput: four separate high-resolution ${item.ratio} images, each a 2×2 grid containing four equal-sized ${item.ratio} panels, intended for ${item.use.toLowerCase()}. Use only narrow, consistent neutral gutters between panels, with no decorative outer border. Each panel should be usable as an independent image after cropping: no subjects crossing panel boundaries, and keep essential details clear of panel edges. No text, lettering, panel labels, numbers, logos, watermarks or mockup interface. Do not add a website headline. Deliver four grid images and 16 visibly different style variations in total.`;
  }
  function node(tag, className, text) {
    const element = document.createElement(tag);
    if (className) element.className = className;
    if (text !== undefined) element.textContent = text;
    return element;
  }
  function announce(message) {
    clearTimeout(noticeTimer);
    notice.textContent = message;
    noticeTimer = setTimeout(() => { notice.textContent = ''; }, 4500);
  }
  async function copy(item, button) {
    const text = fullPrompt(item);
    button.disabled = true;
    try {
      if (!navigator.clipboard?.writeText) throw new Error('Clipboard API unavailable');
      await navigator.clipboard.writeText(text);
      const label = button.querySelector('span');
      label.textContent = 'Prompt copied';
      announce(`${item.id}: complete prompt copied. Ready to paste into your image generator.`);
      setTimeout(() => { label.textContent = 'Copy complete prompt'; }, 2500);
    } catch {
      fallbackText.value = text;
      fallback.showModal();
      fallbackText.focus();
      fallbackText.select();
      fallback.addEventListener('close', () => button.focus(), { once: true });
    } finally { button.disabled = false; }
  }
  function card(item) {
    const article = node('article', 'prompt-card');
    article.dataset.promptId = item.id;
    const art = node('div', 'prompt-card-art'); art.setAttribute('aria-hidden', 'true');
    art.append(node('span', '', 'Image placeholder'), node('span', '', item.ratio));
    const body = node('div', 'prompt-card-body');
    const meta = node('div', 'prompt-card-meta'); meta.append(node('span', '', item.category.name), node('span', '', item.id));
    const heading = node('h2', '', item.title); heading.id = item.id;
    article.setAttribute('aria-labelledby', item.id);
    const details = node('details');
    const summary = node('summary', '', 'Read the complete prompt');
    const prompt = node('p', 'prompt-full-text', fullPrompt(item));
    details.append(summary, prompt);
    const button = node('button', 'prompt-copy'); button.type = 'button';
    button.setAttribute('aria-label', `Copy prompt: ${item.title}`);
    button.append(node('span', '', 'Copy complete prompt'));
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('viewBox', '0 0 24 24'); svg.setAttribute('aria-hidden', 'true');
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', 'M8 8h12v12H8z M16 8V4H4v12h4'); svg.append(path); button.append(svg);
    button.addEventListener('click', () => copy(item, button));
    body.append(meta, heading, node('p', 'prompt-card-use', `${item.use} · ${item.ratio}`), node('p', 'prompt-card-description', item.description), details, button);
    article.append(art, body);
    return article;
  }
  function render() {
    const query = search.value.trim().toLocaleLowerCase('en-NZ');
    const filtered = items.filter(item => (category === 'all' || item.category.id === category) && `${item.id} ${item.title} ${item.use} ${item.description} ${item.scene} ${item.category.name}`.toLocaleLowerCase('en-NZ').includes(query));
    grid.replaceChildren(...filtered.slice(0, limit).map(card));
    count.textContent = `${filtered.length} ${filtered.length === 1 ? 'idea' : 'ideas'}${filtered.length > limit ? ` · ${limit} shown` : ''}`;
    more.hidden = filtered.length <= limit;
    more.firstChild.textContent = `Show ${Math.min(12, filtered.length - limit)} more ideas `;
    document.getElementById('prompt-empty').hidden = filtered.length > 0;
    filters.querySelectorAll('button').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.category === category)));
    document.getElementById('prompt-palette-name').textContent = palette().name;
  }
  for (const entry of [{ id: 'all', name: 'All image ideas', ideas: items }, ...categories]) {
    const button = node('button', '', entry.name); button.type = 'button'; button.dataset.category = entry.id;
    button.append(node('span', '', String(entry.ideas.length)));
    button.addEventListener('click', () => { category = entry.id; limit = 12; render(); });
    filters.append(button);
  }
  search.addEventListener('input', () => { limit = 12; render(); });
  more.addEventListener('click', () => {
    const oldCount = grid.children.length; limit += 12; render();
    const next = grid.children[oldCount];
    if (next) { next.tabIndex = -1; next.focus({ preventScroll: true }); next.scrollIntoView({ behavior: 'auto', block: 'start' }); }
  });
  document.getElementById('prompt-reset').addEventListener('click', () => { category = 'all'; search.value = ''; limit = 12; render(); search.focus(); });
  window.addEventListener('hoea:appearance', () => {
    document.getElementById('prompt-palette-name').textContent = palette().name;
    grid.querySelectorAll('[data-prompt-id]').forEach(article => {
      const item = items.find(entry => entry.id === article.dataset.promptId);
      article.querySelector('.prompt-full-text').textContent = fullPrompt(item);
    });
  });
  // Keep the appearance control beside its explanation, clear of filters/cards.
  const appearanceButton = document.querySelector('.ap-launcher');
  if (appearanceButton) document.querySelector('.prompt-palette-note').after(appearanceButton);
  render();
})();
